package net.hugmesh.adminbff.meshtoken;

import org.springframework.data.annotation.Id;
import org.springframework.data.annotation.PersistenceCreator;
import org.springframework.data.annotation.Transient;
import org.springframework.data.domain.Persistable;
import org.springframework.data.relational.core.mapping.Column;
import org.springframework.data.relational.core.mapping.Table;

import java.time.Instant;

/**
 * One row of {@code mesh_token_issued} (Liquibase changeset 390). The PK is the token's own
 * 16-hex {@code id}, generated by the issuer, so the row implements {@link Persistable} and a
 * new issue INSERTs. No column holds a secret.
 */
@Table("mesh_token_issued")
public record MeshTokenIssuedRow(
        @Id @Column("id") String id,
        @Column("mesh") String mesh,
        @Column("domain") String domain,
        @Column("role") String role,
        @Column("shell") boolean shell,
        @Column("login_server") String loginServer,
        @Column("issuer_fingerprint") String issuerFingerprint,
        @Column("preauth_key_id") String preauthKeyId,
        @Column("node_name") String nodeName,
        @Column("issued_by") String issuedBy,
        @Column("issued_at") Instant issuedAt,
        @Column("expires_at") Instant expiresAt,
        @Transient boolean isNew) implements Persistable<String> {

    @PersistenceCreator
    public MeshTokenIssuedRow(String id, String mesh, String domain, String role, boolean shell,
                              String loginServer, String issuerFingerprint, String preauthKeyId,
                              String nodeName, String issuedBy, Instant issuedAt, Instant expiresAt) {
        this(id, mesh, domain, role, shell, loginServer, issuerFingerprint, preauthKeyId, nodeName,
                issuedBy, issuedAt, expiresAt, false);
    }

    MeshTokenIssued toDomain() {
        return new MeshTokenIssued(id, mesh, domain, role, shell, loginServer, issuerFingerprint,
                preauthKeyId, nodeName == null ? "" : nodeName, issuedBy, issuedAt, expiresAt);
    }

    @Override
    public String getId() {
        return id;
    }

    @Override
    public boolean isNew() {
        return isNew;
    }
}
